INSERT INTO it_glossary (term_ja, reading, term_ko, term_en, category, description, example_sentence) VALUES
  ('SQL', 'エスキューエル', 'SQL', 'Structured Query Language', 'development', '데이터베이스를 조작하고 관리하기 위한 표준 프로그래밍 언어입니다.', 'SQLを使ってデータベースからデータを取得してください。'),
  ('データベース', 'データベース', '데이터베이스', 'Database', 'development', '대량의 데이터를 체계적으로 정리하여 저장하고 검색할 수 있도록 한 시스템입니다.', 'データベースの構造を設計してからテーブルを作成します。'),
  ('正規化', 'せいきか', '정규화', 'Normalization', 'development', '데이터의 중복을 없애고 일관성을 유지하기 위해 테이블 구조를 최적화하는 과정입니다.', '正規化を行ってデータの重複を排除しましょう。'),
  ('主キー', 'しゅきー', '기본키', 'Primary Key', 'development', '테이블에서 각 행(레코드)을 고유하게 식별하기 위한 열(컬럼)입니다. 중복값을 가질 수 없습니다.', 'テーブルに主キーを設定してレコードを一意に識別できるようにします。'),
  ('外部キー', 'がいぶきー', '외래키', 'Foreign Key', 'development', '다른 테이블의 기본키를 참조하여 테이블 간의 관계를 정의하는 열입니다.', '外部キーを設定してテーブル間の参照整合性を保ちます。'),
  ('トランザクション', 'トランザクション', '트랜잭션', 'Transaction', 'development', '데이터베이스에 대한 일련의 처리를 하나의 단위로 묶은 것입니다. 전부 성공하거나 전부 취소됩니다.', 'トランザクションを使って複数の更新処理をまとめて実行します。'),
  ('ACID特性', 'アシッドとくせい', 'ACID 특성', 'ACID Properties', 'development', '트랜잭션이 안전하게 처리되기 위한 4가지 조건(원자성, 일관성, 독립성, 영속성)입니다.', 'ACID特性を満たすことでデータの整合性が保証されます。'),
  ('インデックス', 'インデックス', '인덱스', 'Index', 'development', '데이터베이스에서 검색 속도를 높이기 위해 만드는 색인입니다. 책의 목차와 비슷한 역할을 합니다.', 'よく検索されるカラムにインデックスを作成してパフォーマンスを改善します。'),
  ('ビュー', 'ビュー', '뷰', 'View', 'development', '하나 이상의 테이블에서 필요한 데이터만 골라 만든 가상 테이블입니다.', 'ビューを作成して必要なカラムだけを表示するようにしました。'),
  ('ストアドプロシージャ', 'ストアドプロシージャ', '저장 프로시저', 'Stored Procedure', 'development', '자주 사용하는 SQL 처리를 미리 데이터베이스에 저장해두고 호출하여 사용하는 프로그램입니다.', 'ストアドプロシージャを使って複雑な処理をサーバー側で実行します。'),
  ('トリガー', 'トリガー', '트리거', 'Trigger', 'development', '데이터베이스에서 특정 이벤트(삽입, 수정, 삭제)가 발생하면 자동으로 실행되는 처리입니다.', 'データ更新時に自動でログを記録するトリガーを設定しました。'),
  ('デッドロック', 'デッドロック', '교착 상태', 'Deadlock', 'development', '두 개 이상의 처리가 서로 상대방의 자원을 기다리며 무한히 대기하는 상태입니다.', 'デッドロックが発生した場合、片方のトランザクションをロールバックします。'),
  ('排他制御', 'はいたせいぎょ', '배타 제어', 'Exclusive Control', 'development', '여러 사용자가 동시에 같은 데이터를 수정하지 못하도록 잠금을 거는 것입니다.', '排他制御を実装してデータの不整合を防止します。'),
  ('リレーショナルデータベース', 'リレーショナルデータベース', '관계형 데이터베이스', 'Relational Database', 'development', '데이터를 행과 열로 구성된 테이블 형태로 저장하고, 테이블 간의 관계를 정의하여 관리하는 데이터베이스입니다.', 'リレーショナルデータベースでテーブル間の関係を定義しています。'),
  ('NoSQL', 'ノーエスキューエル', 'NoSQL', 'NoSQL', 'development', '관계형 데이터베이스가 아닌 형태의 데이터베이스 총칭입니다. 대량의 비정형 데이터 처리에 적합합니다.', 'NoSQLデータベースを使って柔軟なデータ構造に対応しています。'),
  ('スキーマ', 'スキーマ', '스키마', 'Schema', 'development', '데이터베이스의 구조를 정의한 설계도입니다. 테이블, 컬럼, 관계 등이 포함됩니다.', 'データベースのスキーマを確認してからマイグレーションを実行します。'),
  ('テーブル', 'テーブル', '테이블', 'Table', 'development', '데이터베이스에서 데이터를 행과 열로 정리하여 저장하는 기본 단위입니다.', '新しいテーブルを作成してユーザー情報を管理します。'),
  ('レコード', 'レコード', '레코드', 'Record', 'development', '데이터베이스 테이블에서 한 행에 해당하는 데이터 단위입니다.', 'レコードを追加してデータベースにユーザーを登録します。'),
  ('フィールド', 'フィールド', '필드', 'Field', 'development', '데이터베이스 테이블에서 한 열(컬럼)에 해당하는 항목입니다.', '必須フィールドにNULLが入らないよう制約を設定してください。'),
  ('NULL', 'ヌル', 'NULL', 'NULL', 'development', '데이터베이스에서 값이 없음, 미정, 알 수 없음을 나타내는 특수한 상태입니다.', 'NULLチェックを行ってエラーを防止してください。'),
  ('JOIN', 'ジョイン', 'JOIN', 'JOIN', 'development', '두 개 이상의 테이블을 공통 열을 기준으로 결합하여 데이터를 조회하는 SQL 연산입니다.', 'JOINを使って複数のテーブルからデータを結合して取得します。'),
  ('GROUP BY', 'グループバイ', 'GROUP BY', 'GROUP BY', 'development', 'SQL에서 특정 열의 값이 같은 행끼리 그룹으로 묶어 집계하는 구문입니다.', 'GROUP BY句を使って部署ごとの売上を集計します。'),
  ('ORDER BY', 'オーダーバイ', 'ORDER BY', 'ORDER BY', 'development', 'SQL에서 조회 결과를 특정 열의 값 기준으로 오름차순 또는 내림차순으로 정렬하는 구문입니다.', 'ORDER BY句で日付の新しい順にデータを並び替えます。'),
  ('WHERE句', 'ウェアく', 'WHERE절', 'WHERE Clause', 'development', 'SQL에서 조건을 지정하여 필요한 데이터만 필터링하는 구문입니다.', 'WHERE句で条件を指定して必要なデータだけを取得します。'),
  ('サブクエリ', 'サブクエリ', '서브쿼리', 'Subquery', 'development', 'SQL 문 안에 포함된 또 다른 SQL 문입니다. 중첩 질의라고도 합니다.', 'サブクエリを使って複雑な条件でデータを抽出します。'),
  ('バックアップと復元', 'バックアップとふくげん', '백업과 복원', 'Backup and Restore', 'development', '데이터 손실에 대비하여 데이터를 복사(백업)하고, 필요할 때 원래 상태로 되돌리는(복원) 작업입니다.', 'データベースのバックアップと復元の手順を確認しておいてください。'),
  ('レプリケーション', 'レプリケーション', '복제', 'Replication', 'development', '데이터베이스의 내용을 다른 서버에 실시간으로 복제하여 동기화하는 기술입니다.', 'レプリケーションを構成して読み取り負荷を分散させています。'),
  ('シャーディング', 'シャーディング', '샤딩', 'Sharding', 'development', '대량의 데이터를 여러 데이터베이스 서버에 분산하여 저장하는 기술입니다.', 'シャーディングを導入して大量データの処理性能を向上させました。'),
  ('データウェアハウス', 'データウェアハウス', '데이터 웨어하우스', 'Data Warehouse', 'development', '다양한 시스템의 데이터를 통합하여 분석용으로 저장하는 대규모 데이터 저장소입니다.', 'データウェアハウスに蓄積されたデータを分析してレポートを作成します。'),
  ('ビッグデータ', 'ビッグデータ', '빅데이터', 'Big Data', 'development', '기존 도구로는 처리하기 어려울 정도로 방대한 양의 데이터입니다. 이를 분석하여 새로운 가치를 창출합니다.', 'ビッグデータを活用して顧客の行動パターンを分析しています。')
